import{_ as a,a as r,b as o}from"./chunks/f9821b408306879ff46d.CdO9ZVdu.js";import{_ as i,C as l,o as n,c as h,j as e,a as s,E as c,a5 as d}from"./chunks/framework.DNkHA0lr.js";const x=JSON.parse('{"title":"如何撰写真实的内容（社交媒体增长101）","description":"","frontmatter":{"title":"如何撰写真实的内容（社交媒体增长101）","originalTitle":"How To Write Authentic Content (Social Media Growth 101)","date":"2023-01-20","originalUrl":"https://thedankoe.com/letters/dont-get-replaced-by-ai-how-to-write-authentic-content/","minutes":9,"sourceHash":"1a32abef6c0a6a95870cec19eb0fd485e59036fe7d516a86f0c85063f0bc9738","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/dont-get-replaced-by-ai-how-to-write-authentic-content/"}]]},"headers":[],"relativePath":"letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md","filePath":"letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md"}'),m={name:"letters/dont-get-replaced-by-ai-how-to-write-authentic-content.md"};function u(b,p,f,k,_,g){const t=l("ArticleMeta");return n(),h("div",null,[p[0]||(p[0]=e("h1",{id:"如何撰写真实的内容-社交媒体增长101",tabindex:"-1"},[s("如何撰写真实的内容（社交媒体增长101） "),e("a",{class:"header-anchor",href:"#如何撰写真实的内容-社交媒体增长101","aria-label":'Permalink to "如何撰写真实的内容（社交媒体增长101）"'},"​")],-1)),c(t),p[1]||(p[1]=d('<p><a href="https://www.youtube.com/embed/wwtt8lkMRDQ?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><em>人们想要关注的是活生生的人。</em></p><p>他们不想关注一个长着人脸的搜索引擎。</p><p>而且，随着 ChatGPT 和未来迭代的语言 AI 的崛起，真实性比以往任何时候都更加重要。</p><p>每个人都极度渴望人与人之间的连结，而社交媒体并没有提供这一点。</p><p>你可以做到，而且这会为你带来超乎想象的权威性。</p><p>根据我的预测，真实性将成为未来一代创作者的差异化因素（这就是为什么我谈论哲学、自我认知以及其他非商业话题，这些话题实际上能让你在商业中脱颖而出）。</p><p>我直接或间接地与超过5000名创作者合作过，这是他们一次又一次遇到的问题。</p><p><em>这似乎是最让人感到崩溃的问题。</em></p><p>创作者不知道如何将真实的自我融入到内容中。</p><p>这使得人们在事情开始变好之前就放弃了。</p><p>而且，即使你坚持到底，如果你不展示你是谁、你从哪里来，你跟机器人有什么区别？</p><p>更糟的是，那些试图融入多种兴趣的人，不知道如何用一种能带来增长、权威和互动的方式来写作。</p><p>在我们深入探讨如何组织话题、撰写内容以及将1个想法变成10个之前，先摆点我的资历：</p><p>我在3年前开始成为一名创作者。</p><p>我一开始就推出了一款产品，而大多数人会警告不要这么做。</p><p>我写任何我想写的东西，比如情绪管理和自我提升，尽管我的产品是关于网页设计的。</p><p>我时不时地穿插几条网页设计的推文（大概每两天一次？），因为我知道这很重要。</p><p>对于那些担心变现的人来说，最重要的事情是：</p><p>谈论任何你想谈的话题，当你计划推广某个东西时，就多谈论那个话题。</p><p>就这么简单。</p><p>好吧，某种程度上是这样。</p><p>经验教给你的会比我在这里能教你的多得多。</p><p><strong>在我们深入探讨之前：</strong></p><p>第一期 Solopreneur Sprint（一人企业冲刺营）将于2月7日开始。</p><p>在14天内，我们将在你的专属细分领域（niche of one）建立自信，创作20多篇基础内容，并为你的创作者品牌制定一个零成本的增长策略。</p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">&gt;&gt; 如果感兴趣，点击这里查看。</a></p><h2 id="你的话题树" tabindex="-1">你的话题树 <a class="header-anchor" href="#你的话题树" aria-label="Permalink to &quot;你的话题树&quot;">​</a></h2><p>如果你不知道写什么，<a href="https://thedankoe.com/the-most-profitable-niche-is-you-how-to-create-your-niche/" target="_blank" rel="noreferrer">去读读上一封关于将你自己变成细分领域的信。</a></p><p>在那封信中，我们梳理了你的人生故事，并将其变成了书的章节。</p><p>哪些技能和兴趣将帮助你创造理想的未来？</p><p>对于那些已经在路上的人来说，你拥有哪些帮助你实现目标的技能、兴趣和专业知识？</p><p>要明白，不赚钱的兴趣同样能帮助你实现目标。</p><p>如果你理想的未来是内心宁静且不用担心金钱……</p><p>听起来，灵性修养才是解决这一切的关键，而不是钱。所以，别犹豫，把你喜欢谈论的事情加进来。</p><p>额外的好处是，你对那个兴趣的热情会在你的内容中展现出来。</p><p>这些就是我们接下来要用于内容创作的素材。</p><h3 id="选择2-3个你想写的兴趣或技能" tabindex="-1">选择2-3个你想写的兴趣或技能 <a class="header-anchor" href="#选择2-3个你想写的兴趣或技能" aria-label="Permalink to &quot;选择2-3个你想写的兴趣或技能&quot;">​</a></h3><p>这些应该已经浮现在你的脑海中了。</p><p>我在这点上帮不了你太多，因为我不是你。</p><p>如果你没有想写的兴趣，你需要设定一个目标，开始去追求它，并学习哪些东西能帮助你实现目标。</p><h3 id="拓宽与拆解" tabindex="-1">拓宽与拆解 <a class="header-anchor" href="#拓宽与拆解" aria-label="Permalink to &quot;拓宽与拆解&quot;">​</a></h3><p>大多数人从“生物力学运动疗法”这样极其具体的兴趣开始，然后倍感压力，因为很少有人对它感兴趣。</p><p>更进一步，他们再次感到压力，因为他们觉得如果不去谈论那个具体的东西，他们所有的变现潜力就会付之东流。</p><p>事情不是这样运作的，我的朋友。把视角拉远一点。</p><p>假设我的兴趣是：</p><ul><li>网页设计</li><li>举重</li><li>灵性修养</li></ul><p>从这些兴趣出发，我想把它们拓宽到它们所属的宏观市场中。</p><p>网页设计 = 在线商业或广义上的商业。</p><p>举重 = 健美或广义上的健康。</p><p>灵性修养 = 自我实现或自我提升。</p><p>既然我们有了3个可以施展拳脚的广阔市场，我们就需要把它们拆解成话题和子话题。</p><p>这种方法的绝妙之处在于：</p><p>如果你想靠“生物力学运动疗法”这样的兴趣来赚钱，你可以去吸引那些对健康感兴趣的人。</p><p>然后，你可以慢慢提高他们对生物力学运动的认知，并教育他们为什么这很重要。</p><p><em>你不应该</em> <em>只去</em> <em>吸引那些对你的主要兴趣了如指掌的人</em>_。_ 他们凭什么要从你这里买东西呢？</p><p>带着这3个兴趣，拿个笔记本，像这样把它们拆解开来：</p><p><img src="'+a+'" alt=""></p><p>你的工作是在6到12个月内，用各种篇幅的内容覆盖这整个领域。</p><p>你的品牌认知就是这样形成的。</p><h3 id="记住社交杠杆的3大支柱" tabindex="-1">记住社交杠杆的3大支柱 <a class="header-anchor" href="#记住社交杠杆的3大支柱" aria-label="Permalink to &quot;记住社交杠杆的3大支柱&quot;">​</a></h3><p>在开始创作内容之前，我们需要平衡我们所写的内容风格。</p><p>社交杠杆的3大支柱是：增长、真实性和权威性。</p><p>你的内容，在1到2个月的时间跨度里，应该涵盖其中的每一个。</p><p>如果你没有在增长，就调整方向。</p><p>如果你没有产生销量，就调整方向。</p><p>如果你没有获得忠实粉丝，就调整方向。</p><p>随着你获得更多<em>真实世界</em>的反馈，不断迭代。你必须发布内容，哪怕它烂透了。</p><h2 id="如何撰写3篇权威性内容" tabindex="-1">如何撰写3篇权威性内容 <a class="header-anchor" href="#如何撰写3篇权威性内容" aria-label="Permalink to &quot;如何撰写3篇权威性内容&quot;">​</a></h2><p>为此，我们将撰写推文。</p><p>为什么？因为推文的长度和结构，非常适合在任何平台上打造成高表现的帖子。</p><p>我的 LinkedIn 帖子、Instagram 帖子和短视频（Reels）、TikTok 视频以及其他内容，全都是基于我的推文创作的。</p><p>我们首先要在你的主要兴趣——也就是那个能为你赚钱的兴趣上建立权威。</p><p>我们将以“营销”为例。</p><p>对于以下任何例子，你可以：</p><ul><li>将它们变成推特长文或时事通讯以获得更多权威性</li><li>将列表中的任何一点重新组合，变成独立的帖子</li><li>将它们复制粘贴到其他平台</li><li>把它们用作 Shorts、Reels 或 TikToks 的文案脚本</li></ul><p>让我们开始吧。</p><h3 id="可落地的原则" tabindex="-1">可落地的原则 <a class="header-anchor" href="#可落地的原则" aria-label="Permalink to &quot;可落地的原则&quot;">​</a></h3><p>很简单，写一个列表，列出新手可以采取的、具有可操作性的步骤。</p><p>这能帮你建立在某个兴趣领域里的权威。而且，就算是高阶玩家也会关注你，因为他们懂基础原则的重要性。</p><p>对于所有这些内容，请记住你应当遵循“钩子 &gt; 主体 &gt; 结论”的结构。</p><blockquote><p>你的内容烂透了，因为你没有：</p><p>– 用钩子抓住读者</p><p>– 痛戳他们的问题</p><p>– 与他们的问题共情</p><p>– 给他们一个有价值的解决方案</p><p>人类心理学永远能打败你自以为管用的东西。</p><p>追求清晰，而不是抖机灵。</p></blockquote><p>这些都是我现写的，所以不会太完美，但请跟着我一起做。</p><p>选一个你的主要兴趣，精心设计一个钩子，提供可落地的价值，最后做个漂亮的总结。</p><p>熟能生巧。</p><h3 id="某个话题的重要性" tabindex="-1">某个话题的重要性 <a class="header-anchor" href="#某个话题的重要性" aria-label="Permalink to &quot;某个话题的重要性&quot;">​</a></h3><p>大多数人不在乎你写什么，因为他们不理解这事的重要性。</p><p>所以，与其卷铺盖走人并抱怨大环境……</p><p>不如教教他们这为什么重要。</p><p><em>这就是你如何让自己的兴趣引起别人兴趣的方法。</em></p><p>让他们意识到这会如何影响他们的生活。</p><blockquote><p>营销是你所能学到的最伟大的技能。</p><p>为什么？</p><p>– 它能与任何其他技能结合</p><p>– 它教你懂人类心理学</p><p>– 它帮你将细分领域的兴趣变现</p><p>只有傻瓜才会指望在不学习如何将“刷帖人”转化为客户的技能的情况下就能赚钱。</p></blockquote><p>这里有个很棒的例子，是我从推特上 Taylin Simmonds 那里借鉴来的：</p><p><img src="'+r+'" alt=""></p><p>试一试吧。</p><p>你的核心话题为什么重要？</p><p>它如何影响了你的生活？</p><p>为什么其他人要在乎？</p><p>自我反思一下，然后就此写篇帖子。</p><h3 id="指出常见错误或问题" tabindex="-1">指出常见错误或问题 <a class="header-anchor" href="#指出常见错误或问题" aria-label="Permalink to &quot;指出常见错误或问题&quot;">​</a></h3><p>在你的话题领域建立权威的一个极佳方式，就是去指出那些糟糕的建议、常见的错误或者问题。</p><p>这表明你经验丰富，而且你真心想帮助你的读者。</p><blockquote><p>停止写极其极其具体的内容。</p><p>作为新手，你的重点应该放在增长上。</p><p>– 让你的写作能引起共鸣</p><p>– 聚焦于一个普遍的问题</p><p>– 从更高的视角来谈论这个话题</p><p>如果只有极少数人愿意分享你的内容，就别指望能获得增长。</p></blockquote><p>这就引出了我的下一个建议。</p><h2 id="如何让你的写作发挥最大价值" tabindex="-1">如何让你的写作发挥最大价值 <a class="header-anchor" href="#如何让你的写作发挥最大价值" aria-label="Permalink to &quot;如何让你的写作发挥最大价值&quot;">​</a></h2><p>新手创作者常常难以看清内容创作的全貌。</p><p>你并非要让每一篇帖子都能立即带来销量。</p><p>你的帖子不是销售页面（但懂得如何写销售页面会对你写帖子有帮助）。</p><p>当你审视自己的文章时，它能不能被社交媒体上刷帖的普通人分享，这应该是一目了然的。</p><p>如果不能，而你在自己的细分领域里又没有增长策略，那你指望怎么实现增长？</p><p>转发分享是品牌自然增长的引擎。</p><p>拉大视角去明白一点：随着时间的推移，你的内容将会把你所提供的价值介绍给人们。</p><p>时机成熟时，如果你具备实力，他们自然会买你的单。</p><h3 id="拓宽你的内容" tabindex="-1">拓宽你的内容 <a class="header-anchor" href="#拓宽你的内容" aria-label="Permalink to &quot;拓宽你的内容&quot;">​</a></h3><p>从我上面写的那些推文来看，它们具有权威性吗？</p><p>是的。</p><p>它们会吸引潜在客户吗（假设在我的内容之外他们能找到我提供的更多价值）？</p><p>会的。</p><p>它们是不是太过于具体导致没人愿意分享？</p><p>不会。</p><p>这就是你在社交媒体的漏斗顶部必须把握的平衡。</p><p>接着，当你把他们引流到你的时事通讯、引流品以及产品销售页面时——那里才是你想多具体就多具体的地方。</p><p>如果你的内容看起来不会被一个新手分享，那就把视角拉高一层，重写一遍。</p><h3 id="研究最佳的内容结构" tabindex="-1">研究最佳的内容结构 <a class="header-anchor" href="#研究最佳的内容结构" aria-label="Permalink to &quot;研究最佳的内容结构&quot;">​</a></h3><p>在我们开始写列表以外的内容之前，我建议你去研究一下优质内容长什么样。</p><p>我个人使用 <a href="http://tweethunter.io/?via=thedankoe" target="_blank" rel="noreferrer">TweetHunter</a>（一款软件）和 Twemex（一款 Chrome 插件）来快速查看我喜欢的账号的热门内容。</p><p>你也可以使用推特的高级搜索来实现这一点，通过输入：</p><p><em>from:thedankoe min_faves:1000</em></p><p>到你的推特搜索栏中。</p><p>只需把我的用户名替换成别人的，再把最低点赞数改成你想要的任何数字。</p><p>沉浸在那些内容中，并把它们当成你起步时的“辅助轮”。</p><p>你要用什么话题来进行这种练习呢？</p><h3 id="重新利用你的列表式内容" tabindex="-1">重新利用你的列表式内容 <a class="header-anchor" href="#重新利用你的列表式内容" aria-label="Permalink to &quot;重新利用你的列表式内容&quot;">​</a></h3><p>你上面写的列表有多个要点，每一个要点都可以转化成独立的内容。</p><p>这些列表还可以变成一篇推特长文、轮播图或者时事通讯的提纲。</p><p>（我强烈建议这么做，以便进一步建立你的权威）。</p><p>现在，让我们集中精力再写一篇简短的帖子。</p><p>在我们上面写的第一条推文中，第一个要点是“用钩子抓住你的读者”。</p><p>如果我拿出一个我表现极佳的推文结构，比如这条获得了9000个赞的推文：</p><p><img src="'+o+'" alt=""></p><p>那么我就能写出一条新推文：</p><p>最伟大的数字技能，是捕获注意力、留住注意力并在其上交付价值的能力。</p><p>这条还可以写得更好，但我知道它绝对会有不错的表现。</p><p>你可以看出，如果你针对自己所有的兴趣都遵循这些确切的步骤，所有这些内容写作的事情会有多简单。</p><p>总结一下：</p><ul><li>你可以，也应该，融入你的兴趣，使你的品牌显得真实</li><li>创建一个主题树，让你能在6到12个月内通过写作来精通它</li><li>撰写多篇列表形式的内容，在你的主要兴趣上建立权威</li><li>如果你认为内容不会被分享，那就拓宽你的写作范围</li><li>研究最优秀的内容结构，将其作为辅助轮，并从你已写过的内容中衍生出新内容</li></ul><p>这就是你开始内容创作所需的一切。</p><p>在下一封信中，我们将讨论如何不花一分钱就能让这些内容获得分享。</p><p>希望你们喜欢这篇，我的朋友们。</p><p>下次聊。</p><p>– DK</p><p><strong>当你准备好时，我能如何帮助你</strong></p><p>Solopreneur Sprints 于2月7日开始。我们将打造你的一人细分领域，一起撰写20多篇内容，并制定一套增长策略，让你最终能全职做这件事。</p><p><a href="https://sprints.digitaleconomics.school/" target="_blank" rel="noreferrer">点击此处以150美元报名。</a></p><p>2 Hour Writer 教你在实战环境中进行高影响力的创意写作。我将帮你构建内容生态系统，让你在茫茫创作者之海中脱颖而出。</p><p><a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">点击此处报名2HW。</a></p><p>Modern Mastery 是一个涵盖营销、销售、个人成长和高效表现的私密社区。加入即可立即解锁策略库，在 Discord 中获得个性化帮助等更多权益。</p><p><a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以5美元加入。</a></p><hr><p><a href="/en/letters/dont-get-replaced-by-ai-how-to-write-authentic-content">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',160))])}const P=i(m,[["render",u]]);export{x as __pageData,P as default};
